import 'dart:convert';
import 'dart:typed_data';

/// Genuine non-production, self-signed X.509 leaf certificates encoded as DER.
///
/// The source intentionally contains only certificate bytes: generation keys and
/// PEM intermediates are kept outside the repository.
Uint8List _der(String encoded) => Uint8List.fromList(base64Decode(encoded));

